impl Solution{pub fn valid_tree(n:i32,e:Vec<Vec<i32>>)->bool{if e.len()!=n as usize-1{return false}let n=n as usize;let mut g=vec![vec![];n];for x in e{g[x[0]as usize].push(x[1]as usize);g[x[1]as usize].push(x[0]as usize);}let mut st=vec![0];let mut v=vec![false;n];while let Some(u)=st.pop(){if v[u]{continue}v[u]=true;for &x in &g[u]{if !v[x]{st.push(x)}}}v.into_iter().all(|x|x)}}
